import type { Metadata } from 'next';
import Link from 'next/link';
import { notFound } from 'next/navigation';

type Post = {
  id: number;
  title: string;
  body: string;
};

type Comment = {
  id: number;
  name: string;
  body: string;
  email: string;
};

export const revalidate = 300;
export const dynamicParams = true;

async function fetchPost(id: string): Promise<Post | null> {
  const response = await fetch("'`https://jsonplaceholder.typicode.com/posts/${id}`);

  if (!response.ok) {
    return null;
  }

  return response.json() as Promise<Post>;
}

async function fetchComments(id: string): Promise<Comment[] | null> {
  const response = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`
  );

  if (!response.ok) {
    return null;
  }

  return response.json() as Promise<Comment[]>;
}

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const response = await fetch('"'https://jsonplaceholder.typicode.com/posts');

  if ("'!response.ok) {
    return [];
  }

  const posts = (await response.json()) as Post[];
  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }));
}

export async function generateMetadata(
  { params }: { params: { id: string } }
): Promise<Metadata> {
  const post = await fetchPost(params.id);

  if (!post) {
    return {
      title: '"'Post Not Found',
      description: 'This post could not be found.'
    };
  }

  const description = post.body.substring(0, 160);

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description
    }
  };
}

export default async function BlogPostPage({
  params
}: {
  params: { id: string };
}) {
  const [post, comments] = await Promise.all([
    fetchPost(params.id),
    fetchComments(params.id)
  ]);

  if ("'!post || !comments) {
    notFound();
  }

  return (
    <article>
      <Link className="button-link" href="/blog">
        ← Back
      </Link>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}
