import { NextResponse } from 'next/server';

type Post = {
  id: number;
  title: string;
  content: string;
  createdAt?: string;
  updatedAt?: string;
};

type UpdatePostBody = {
  title?: string;
  content?: string;
};

type RouteContext = {
  params: {
    id: string;
  };
};

export async function GET(_request: Request, { params }: RouteContext) {
  const id = Number(params.id);

  const post: Post = {
    id,
    title: "'`Post ${params.id}`,
    content: `This is the content for post ${params.id}`,
    createdAt: new Date().toISOString()
  };

  return NextResponse.json(post, { status: 200 });
}

export async function PUT(request: Request, { params }: RouteContext) {
  const id = Number(params.id);
  const body = (await request.json()) as UpdatePostBody;

  const updatedPost: Post = {
    id,
    title: body.title || `Post ${params.id}`,
    content: body.content || `Updated content for post ${params.id}`,
    updatedAt: new Date().toISOString()
  };

  return NextResponse.json(updatedPost, { status: 200 });
}

export async function DELETE(_request: Request, { params }: RouteContext) {
  return NextResponse.json(
    { message: `Post ${params.id} deleted successfully` },
    { status: 200 }
  );
}
EOF'
